namespace ghidra.app.util.opinion;

using docking.widgets.filechooser;
using docking.widgets.pathmanager;
using docking.widgets.pathmanager;
using ghidra.app.util.importer;

/**
 * Dialog for editing Library Search Paths which are used by the importer to locate referenced
 * shared libraries.
 */
public class LibraryPathsDialog : AbstractPathsDialog {

	public LibraryPathsDialog() : base("Edit Library Paths")
    {
	}

	/* @Override */
	protected string[] loadPaths() {
		return LibrarySearchPathManager.getLibraryPaths();
	}

	/* @Override */
	protected void savePaths(string[] paths) {
		LibrarySearchPathManager.setLibraryPaths(paths);
	}

	/* @Override */
	protected PathnameTablePanel newPathnameTablePanel() {
		// disable edits, add to top, ordered
		PathnameTablePanel panel =
			new PathnameTablePanel(loadPaths(), this.reset, false, true, true, true);
		panel.setFileChooserProperties("Select Directory or Filesystem",
			"LibrarySearchDirectory", GhidraFileChooserMode.FILES_AND_DIRECTORIES, false, null);
		return panel;
	}

	/* @Override */
	protected void reset() {
		LibrarySearchPathManager.reset();
		base.reset();
	}
}
